    }

    private Integer calcularPrazo(ModalidadeEntrega modalidade) {
        return switch (modalidade) {
            case ECONOMICA -> 7;
            case EXPRESSA -> 2;
            case RETIRADA_LOJA -> 1;
            case MOTOBOY -> 0;
